from __future__ import annotations

import logging
import subprocess
import time
from typing import Optional, TextIO, Union

import psutil  # type: ignore

logger: logging.Logger = logging.getLogger("pmi_ticket_collector.tunnel")


class SSHTunnelError(Exception):
    pass


class Tunnel:
    __slots__ = [
        "_started",
        "_cu_ip",
        "_local_ip",
        "_cpue_ip",
        "_tun_name",
        "_process",
        "_logger",
        "_username",
        "_password",
    ]

    def __init__(self, cu_ip: str, local_ip: str, cpue_ip: str, tun_name: str, username: str, password: str) -> None:
        self._started = False
        self._cu_ip: str = cu_ip
        self._local_ip: str = local_ip
        self._cpue_ip: str = cpue_ip
        self._tun_name: str = tun_name
        self._username: str = username
        self._password: str = password
        self._process: psutil.Process = None

    def __str__(self) -> str:
        return (
            f"CU_IP: {self._cu_ip}, CPUE_IP: {self._cpue_ip}, local IP: {self._local_ip}, "
            f"tun_name: {self._tun_name}, PID: {self._process.pid if self._process else None},"
            f" is alive: {self._process.is_running() if self._process else None}"
        )

    def close(self, ssh_fhd: Union[Optional[TextIO], int]) -> None:
        cmd = f"ssh {self._username}@{self._cu_ip} -O exit -S {self._tun_name}"
        logger.debug(f"Executing command {cmd}")
        ssh_fhd = ssh_fhd or subprocess.PIPE
        subprocess.Popen(cmd.split(), stdout=ssh_fhd, stderr=ssh_fhd)
        logger.debug(f"Closed tunnel: {self}")

    def start(self, ssh_fhd: Union[Optional[TextIO], int]) -> None:
        cmd = (
            f"ssh {self._username}@{self._cu_ip} -f -M -N -L "
            f"{self._local_ip}:30512:[{self._cpue_ip}]:30512 -S {self._tun_name}"
        )
        logger.debug(f"Executing command {cmd}")
        try:
            ssh_fhd = ssh_fhd or subprocess.PIPE
            proc = subprocess.Popen(cmd.split(), stdout=ssh_fhd, stderr=ssh_fhd)
            self._find_proper_process(proc)
            logger.debug(f"Created tunnel: {self}")
            self._started = True
        except Exception as err:
            logger.debug(err, exc_info=True)

    def is_alive(self, log: logging.Logger | None = None) -> bool:
        log = log or logger
        log.debug(self)
        if self._started:
            return self._process.is_running()
        else:
            return True

    def _find_proper_process(self, proc: subprocess.Popen) -> None:
        self._wait_for_launching_proc_to_finish(proc)
        t_start = time.time()
        while time.time() - t_start < 10 and not self._process:
            for _proc in (_ for _ in psutil.process_iter() if _.status() != psutil.STATUS_ZOMBIE):
                if self._tun_name in _proc.cmdline():
                    self._process = _proc
                    break
        if not self._process:
            cmd = f"ssh {self._username}@{self._cu_ip} -S {self._tun_name} -O check"
            logger.debug(subprocess.check_output(args=cmd.split()))
            raise ValueError(f"Not found proper process with tun_name: {self._tun_name}")

    @staticmethod
    def _wait_for_launching_proc_to_finish(proc: subprocess.Popen) -> None:
        while proc.poll() is None:
            time.sleep(0.1)
